(function(){'use strict';const zh=document.documentElement.lang.startsWith('zh'),tr=(z,e)=>zh?z:e,el=k=>document.getElementById('M12-'+k);if(!el('plot'))return;
const defaults={kernel:'vertical',stride:1,padding:0,row:2,col:1};let p={...defaults},pixels=initial(),timer=null;
function initial(){return Array.from({length:7},()=>Array.from({length:7},(_,c)=>c>=3?1:0));}
function kernel(){return p.kernel==='vertical'?[[-1,0,1],[-1,0,1],[-1,0,1]]:p.kernel==='horizontal'?[[-1,-1,-1],[0,0,0],[1,1,1]]:Array.from({length:3},()=>[1/9,1/9,1/9]);}
function size(){return Math.floor((7+2*p.padding-3)/p.stride)+1;}
function cell(row,col){const K=kernel(),terms=[];let value=0;for(let u=0;u<3;u++)for(let v=0;v<3;v++){const r=row*p.stride-p.padding+u,c=col*p.stride-p.padding+v,x=r>=0&&r<7&&c>=0&&c<7?pixels[r][c]:0,w=K[u][v];terms.push({input:x,weight:w,product:x*w,row:r,col:c});value+=x*w;}return {value,terms};}
function state(){const n=size(),selected=cell(p.row,p.col);return {...p,outputSize:n,value:selected.value,terms:selected.terms,input:pixels.map(a=>a.slice()),output:Array.from({length:n},(_,r)=>Array.from({length:n},(_,c)=>cell(r,c).value))};}
const fmt=v=>Number.isInteger(v)?String(v):v.toFixed(3);
function draw(){const s=state(),n=s.outputSize;for(const k of ['kernel','stride','padding'])el(k).value=p[k];for(const k of ['row','col']){el(k).max=n-1;el(k).value=p[k];el(k+'-value').textContent=p[k];}
 let h=`<text x="160" y="30" text-anchor="middle" fill="currentColor">${tr('输入：7×7','Input:7×7')}</text><text x="443" y="30" text-anchor="middle" fill="currentColor">${tr('核：3×3','Kernel:3×3')}</text><text x="737" y="30" text-anchor="middle" fill="currentColor">${tr('输出：','Output:')}${n}×${n}</text>`;
 for(let r=0;r<7;r++)for(let c=0;c<7;c++){const x=45+c*33,y=65+r*33;h+=`<g tabindex="0" role="button" data-input="${r},${c}" aria-label="${tr('输入行','Input row')}${r},${tr('列','column')}${c},${tr('值','value')}${pixels[r][c]}"><rect x="${x}" y="${y}" width="32" height="32" fill="${pixels[r][c]?'#234b5b':'#f0f3f4'}" stroke="#c3cfd5"/><text x="${x+16}" y="${y+21}" text-anchor="middle" fill="${pixels[r][c]?'white':'#203841'}" font-size="13">${pixels[r][c]}</text></g>`;}
 const K=kernel();for(let r=0;r<3;r++)for(let c=0;c<3;c++){const x=380+c*42,y=115+r*42;h+=`<rect x="${x}" y="${y}" width="41" height="41" fill="${K[r][c]<0?'#d7e9f2':K[r][c]>0?'#fff0d2':'#f1f3f4'}" stroke="#bdcbd1"/><text x="${x+21}" y="${y+26}" text-anchor="middle" fill="#203841" font-size="14">${p.kernel==='mean'?'1/9':K[r][c]}</text>`;}
 const unit=Math.min(40,250/n),start=610;for(let r=0;r<n;r++)for(let c=0;c<n;c++){const value=s.output[r][c],alpha=Math.min(1,Math.abs(value)/(p.kernel==='mean'?1:3)),color=value<0?`rgba(0,114,178,${.12+.75*alpha})`:`rgba(213,133,0,${.08+.7*alpha})`,x=start+c*unit,y=65+r*unit;h+=`<g tabindex="0" role="button" data-output="${r},${c}" aria-label="${tr('输出行','Output row')}${r},${tr('列','column')}${c},${tr('值','value')}${fmt(value)}"><rect x="${x}" y="${y}" width="${unit-1}" height="${unit-1}" fill="${color}" stroke="${r===p.row&&c===p.col?'#D58500':'#c5d1d7'}" stroke-width="${r===p.row&&c===p.col?3:1}"/><text x="${x+unit/2}" y="${y+unit/2+4}" text-anchor="middle" fill="#203841" font-size="${n>5?10:12}">${fmt(value)}</text></g>`;}
 h+=`<rect x="${45+(p.col*p.stride-p.padding)*33}" y="${65+(p.row*p.stride-p.padding)*33}" width="99" height="99" fill="none" stroke="#D58500" stroke-width="3" pointer-events="none"/><text x="160" y="335" text-anchor="middle" fill="currentColor">${tr('橙框：当前读取范围','Orange: selected patch')}</text><text x="737" y="365" text-anchor="middle" fill="currentColor">${tr('蓝：负响应　橙：正响应','Blue: negative · Orange: positive')}</text><text x="443" y="285" text-anchor="middle" fill="currentColor">${tr('对应位置相乘后求和','Multiply matching entries, then sum')}</text>`;el('plot').innerHTML=h;
 el('products').innerHTML=[0,1,2].map(r=>'<tr>'+s.terms.slice(r*3,r*3+3).map(v=>`<td>${fmt(v.input)} × ${p.kernel==='mean'?'1/9':fmt(v.weight)} = ${fmt(v.product)}</td>`).join('')+'</tr>').join('');el('result').textContent=tr(`输出(${p.row},${p.col}) = ${fmt(s.value)}；输出大小${n}×${n}。输入起点为(${p.row*p.stride-p.padding},${p.col*p.stride-p.padding})。`,`Output(${p.row},${p.col}) = ${fmt(s.value)}; output size${n}×${n}. Input patch starts at(${p.row*p.stride-p.padding},${p.col*p.stride-p.padding}).`);}
function set(v){if(['vertical','horizontal','mean'].includes(v.kernel))p.kernel=v.kernel;if(v.stride!==undefined)p.stride=Number(v.stride)===2?2:1;if(v.padding!==undefined)p.padding=Number(v.padding)===1?1:0;if(Array.isArray(v.input)&&v.input.length===7&&v.input.every(r=>Array.isArray(r)&&r.length===7))pixels=v.input.map(r=>r.map(x=>x?1:0));for(const k of ['row','col'])if(Number.isFinite(Number(v[k])))p[k]=Math.round(+v[k]);p.row=Math.max(0,Math.min(size()-1,p.row));p.col=Math.max(0,Math.min(size()-1,p.col));draw();return state();}
function stop(){if(timer)clearInterval(timer);timer=null;el('play').textContent=tr('扫描','Scan');}function next(){const n=size(),index=p.row*n+p.col+1;set({row:Math.floor((index%(n*n))/n),col:index%n});if(index>=n*n)stop();}function reset(){stop();p={...defaults};pixels=initial();draw();return state();}
for(const k of Object.keys(p))el(k).addEventListener('input',()=>{stop();set({[k]:el(k).value});});
function choose(target){const input=target.closest('[data-input]'),output=target.closest('[data-output]');if(input){const [r,c]=input.dataset.input.split(',').map(Number);pixels[r][c]=1-pixels[r][c];draw();}if(output){const [row,col]=output.dataset.output.split(',').map(Number);set({row,col});}}
el('plot').addEventListener('click',e=>{stop();choose(e.target);});el('plot').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();stop();choose(e.target);}});el('step').addEventListener('click',()=>{stop();next();});el('play').addEventListener('click',()=>{if(timer){stop();return;}el('play').textContent=tr('暂停','Pause');timer=setInterval(next,500);});el('reset').addEventListener('click',reset);window.CourseLab={state,set,reset,destroy:stop};draw();})();
